package apextest

import (
	"encoding/json"
	"path/filepath"
	"testing"
)

func TestRunCurrencyDefaultLifecycleAdmitted(t *testing.T) {
	root := t.TempDir()
	writeFile(t, filepath.Join(root, "force-app/main/default/classes/GladeCurrencyTrace53.cls"), "public class GladeCurrencyTrace53 {\n    public static List<Object> rows = new List<Object>();\n    public static void record(String phase, SObject item) {\n        Map<String,Object> row = new Map<String,Object>{'phase'=>phase,'object'=>String.valueOf(item.getSObjectType()),'currency'=>item.get('CurrencyIsoCode'),'idPresent'=>item.Id != null};\n        if (item instanceof Opportunity && item.get('GladeCurrencyParent__c') != null) {\n            Id parentId = (Id)item.get('GladeCurrencyParent__c');\n            SObject parent = Database.query('SELECT Id,CurrencyIsoCode FROM GladeCurrencyParent__c WHERE Id = :parentId');\n            row.put('queriedParentCurrency',parent.get('CurrencyIsoCode'));\n            row.put('outOfSync',(String)item.get('CurrencyIsoCode') != (String)parent.get('CurrencyIsoCode'));\n        }\n        rows.add(row);\n    }\n}\n")
	writeFile(t, filepath.Join(root, "force-app/main/default/classes/GladeCurrencyTrace53.cls-meta.xml"), "<ApexClass xmlns=\"http://soap.sforce.com/2006/04/metadata\"><apiVersion>53.0</apiVersion><status>Active</status></ApexClass>\n")
	writeFile(t, filepath.Join(root, "force-app/main/default/classes/GladeCurrencyDefaultsObserve53.cls"), "@IsTest private class GladeCurrencyDefaultsObserve53 {\n    private static void probe(String mode) {\n        System.assertEquals(true, UserInfo.isMultiCurrencyOrganization(), 'PREREQUISITE: MultiCurrency org required');\n        GladeCurrencyTrace53.rows.clear();\n        Map<String,Object> out = new Map<String,Object>{'mode'=>mode,'multiCurrency'=>UserInfo.isMultiCurrencyOrganization(),'userDefault'=>UserInfo.getDefaultCurrency()};\n        List<Object> descriptors=new List<Object>();\n        for (Schema.SObjectType t : new List<Schema.SObjectType>{GladeCurrencyParent__c.SObjectType,Opportunity.SObjectType}) {\n            Schema.DescribeFieldResult f=t.getDescribe().fields.getMap().get('CurrencyIsoCode').getDescribe();\n            descriptors.add(new Map<String,Object>{'object'=>String.valueOf(t),'type'=>String.valueOf(f.getType()),'defaultedOnCreate'=>f.isDefaultedOnCreate(),'defaultValue'=>f.getDefaultValue(),'newSObjectWithDefaultsCurrency'=>t.newSObject(null,true).get('CurrencyIsoCode')});\n        }\n        out.put('descriptors',descriptors);\n        out.put('corporateCurrencies',[SELECT IsoCode,IsActive,IsCorporate,ConversionRate FROM CurrencyType WHERE IsCorporate=true]);\n        out.put('activeCurrencyCount',[SELECT COUNT() FROM CurrencyType WHERE IsActive=true]);\n        GladeCurrencyParent__c parent=new GladeCurrencyParent__c(Name='Currency parent',Amount__c=100);\n        if(mode=='null') parent.put('CurrencyIsoCode',null);\n        if(mode=='explicit') parent.put('CurrencyIsoCode',UserInfo.getDefaultCurrency());\n        GladeCurrencyTrace53.record('parentConstructed',parent);\n        try {\n            insert parent;\n            GladeCurrencyTrace53.record('parentInputAfterInsert',parent);\n            GladeCurrencyTrace53.record('parentQueriedAfterInsert',[SELECT Id,CurrencyIsoCode FROM GladeCurrencyParent__c WHERE Id=:parent.Id]);\n            OpportunityStage stage=[SELECT MasterLabel FROM OpportunityStage WHERE IsActive=true LIMIT 1];\n            Opportunity opp=new Opportunity(Name='Currency opportunity',StageName=stage.MasterLabel,CloseDate=Date.newInstance(2026,5,2),Amount=100,GladeCurrencyParent__c=parent.Id);\n            if(mode=='null') opp.put('CurrencyIsoCode',null);\n            if(mode=='explicit') opp.put('CurrencyIsoCode',UserInfo.getDefaultCurrency());\n            GladeCurrencyTrace53.record('opportunityConstructed',opp);\n            insert opp;\n            GladeCurrencyTrace53.record('opportunityInputAfterInsert',opp);\n            GladeCurrencyTrace53.record('opportunityQueriedAfterInsert',[SELECT Id,CurrencyIsoCode,GladeCurrencyParent__c FROM Opportunity WHERE Id=:opp.Id]);\n            out.put('completed',true);\n        } catch (Exception e) {out.put('errorType',e.getTypeName());out.put('errorMessage',e.getMessage());out.put('completed',false);}\n        out.put('rows',GladeCurrencyTrace53.rows);\n        verifyCurrencyObservation(out,mode);\n    }\n    @IsTest static void omittedCurrencies() {probe('omitted');}\n    @IsTest static void explicitNullCurrencies() {probe('null');}\n    @IsTest static void explicitUserDefaultCurrencies() {probe('explicit');}\n\n    private static void verifyCurrencyObservation(Map<String,Object> observed,String mode) {\n        String expectedJSON;\n        if(mode=='omitted')expectedJSON='{\"rows\":[{\"idPresent\":false,\"currency\":null,\"object\":\"GladeCurrencyParent__c\",\"phase\":\"parentConstructed\"},{\"idPresent\":false,\"currency\":\"USD\",\"object\":\"GladeCurrencyParent__c\",\"phase\":\"beforeInsert\"},{\"idPresent\":true,\"currency\":\"USD\",\"object\":\"GladeCurrencyParent__c\",\"phase\":\"afterInsert\"},{\"idPresent\":true,\"currency\":null,\"object\":\"GladeCurrencyParent__c\",\"phase\":\"parentInputAfterInsert\"},{\"idPresent\":true,\"currency\":\"USD\",\"object\":\"GladeCurrencyParent__c\",\"phase\":\"parentQueriedAfterInsert\"},{\"outOfSync\":true,\"queriedParentCurrency\":\"USD\",\"idPresent\":false,\"currency\":null,\"object\":\"Opportunity\",\"phase\":\"opportunityConstructed\"},{\"outOfSync\":false,\"queriedParentCurrency\":\"USD\",\"idPresent\":false,\"currency\":\"USD\",\"object\":\"Opportunity\",\"phase\":\"beforeInsert\"},{\"outOfSync\":false,\"queriedParentCurrency\":\"USD\",\"idPresent\":true,\"currency\":\"USD\",\"object\":\"Opportunity\",\"phase\":\"afterInsert\"},{\"outOfSync\":true,\"queriedParentCurrency\":\"USD\",\"idPresent\":true,\"currency\":null,\"object\":\"Opportunity\",\"phase\":\"opportunityInputAfterInsert\"},{\"outOfSync\":false,\"queriedParentCurrency\":\"USD\",\"idPresent\":true,\"currency\":\"USD\",\"object\":\"Opportunity\",\"phase\":\"opportunityQueriedAfterInsert\"}],\"completed\":true,\"activeCurrencyCount\":1,\"corporateCurrencies\":[{\"attributes\":{\"type\":\"CurrencyType\",\"url\":\"<generated-currency-url>\"},\"IsoCode\":\"USD\",\"IsActive\":true,\"IsCorporate\":true,\"ConversionRate\":1.0,\"Id\":\"<generated-currency-id>\"}],\"descriptors\":[{\"newSObjectWithDefaultsCurrency\":\"USD\",\"defaultValue\":\"USD\",\"defaultedOnCreate\":true,\"type\":\"PICKLIST\",\"object\":\"GladeCurrencyParent__c\"},{\"newSObjectWithDefaultsCurrency\":\"USD\",\"defaultValue\":\"USD\",\"defaultedOnCreate\":true,\"type\":\"PICKLIST\",\"object\":\"Opportunity\"}],\"userDefault\":\"USD\",\"multiCurrency\":true,\"mode\":\"omitted\"}';\n        else if(mode=='null')expectedJSON='{\"rows\":[{\"idPresent\":false,\"currency\":null,\"object\":\"GladeCurrencyParent__c\",\"phase\":\"parentConstructed\"},{\"idPresent\":false,\"currency\":null,\"object\":\"GladeCurrencyParent__c\",\"phase\":\"beforeInsert\"},{\"idPresent\":true,\"currency\":\"USD\",\"object\":\"GladeCurrencyParent__c\",\"phase\":\"afterInsert\"},{\"idPresent\":true,\"currency\":null,\"object\":\"GladeCurrencyParent__c\",\"phase\":\"parentInputAfterInsert\"},{\"idPresent\":true,\"currency\":\"USD\",\"object\":\"GladeCurrencyParent__c\",\"phase\":\"parentQueriedAfterInsert\"},{\"outOfSync\":true,\"queriedParentCurrency\":\"USD\",\"idPresent\":false,\"currency\":null,\"object\":\"Opportunity\",\"phase\":\"opportunityConstructed\"},{\"outOfSync\":true,\"queriedParentCurrency\":\"USD\",\"idPresent\":false,\"currency\":null,\"object\":\"Opportunity\",\"phase\":\"beforeInsert\"},{\"outOfSync\":false,\"queriedParentCurrency\":\"USD\",\"idPresent\":true,\"currency\":\"USD\",\"object\":\"Opportunity\",\"phase\":\"afterInsert\"},{\"outOfSync\":true,\"queriedParentCurrency\":\"USD\",\"idPresent\":true,\"currency\":null,\"object\":\"Opportunity\",\"phase\":\"opportunityInputAfterInsert\"},{\"outOfSync\":false,\"queriedParentCurrency\":\"USD\",\"idPresent\":true,\"currency\":\"USD\",\"object\":\"Opportunity\",\"phase\":\"opportunityQueriedAfterInsert\"}],\"completed\":true,\"activeCurrencyCount\":1,\"corporateCurrencies\":[{\"attributes\":{\"type\":\"CurrencyType\",\"url\":\"<generated-currency-url>\"},\"IsoCode\":\"USD\",\"IsActive\":true,\"IsCorporate\":true,\"ConversionRate\":1.0,\"Id\":\"<generated-currency-id>\"}],\"descriptors\":[{\"newSObjectWithDefaultsCurrency\":\"USD\",\"defaultValue\":\"USD\",\"defaultedOnCreate\":true,\"type\":\"PICKLIST\",\"object\":\"GladeCurrencyParent__c\"},{\"newSObjectWithDefaultsCurrency\":\"USD\",\"defaultValue\":\"USD\",\"defaultedOnCreate\":true,\"type\":\"PICKLIST\",\"object\":\"Opportunity\"}],\"userDefault\":\"USD\",\"multiCurrency\":true,\"mode\":\"null\"}';\n        else if(mode=='explicit')expectedJSON='{\"rows\":[{\"idPresent\":false,\"currency\":\"USD\",\"object\":\"GladeCurrencyParent__c\",\"phase\":\"parentConstructed\"},{\"idPresent\":false,\"currency\":\"USD\",\"object\":\"GladeCurrencyParent__c\",\"phase\":\"beforeInsert\"},{\"idPresent\":true,\"currency\":\"USD\",\"object\":\"GladeCurrencyParent__c\",\"phase\":\"afterInsert\"},{\"idPresent\":true,\"currency\":\"USD\",\"object\":\"GladeCurrencyParent__c\",\"phase\":\"parentInputAfterInsert\"},{\"idPresent\":true,\"currency\":\"USD\",\"object\":\"GladeCurrencyParent__c\",\"phase\":\"parentQueriedAfterInsert\"},{\"outOfSync\":false,\"queriedParentCurrency\":\"USD\",\"idPresent\":false,\"currency\":\"USD\",\"object\":\"Opportunity\",\"phase\":\"opportunityConstructed\"},{\"outOfSync\":false,\"queriedParentCurrency\":\"USD\",\"idPresent\":false,\"currency\":\"USD\",\"object\":\"Opportunity\",\"phase\":\"beforeInsert\"},{\"outOfSync\":false,\"queriedParentCurrency\":\"USD\",\"idPresent\":true,\"currency\":\"USD\",\"object\":\"Opportunity\",\"phase\":\"afterInsert\"},{\"outOfSync\":false,\"queriedParentCurrency\":\"USD\",\"idPresent\":true,\"currency\":\"USD\",\"object\":\"Opportunity\",\"phase\":\"opportunityInputAfterInsert\"},{\"outOfSync\":false,\"queriedParentCurrency\":\"USD\",\"idPresent\":true,\"currency\":\"USD\",\"object\":\"Opportunity\",\"phase\":\"opportunityQueriedAfterInsert\"}],\"completed\":true,\"activeCurrencyCount\":1,\"corporateCurrencies\":[{\"attributes\":{\"type\":\"CurrencyType\",\"url\":\"<generated-currency-url>\"},\"IsoCode\":\"USD\",\"IsActive\":true,\"IsCorporate\":true,\"ConversionRate\":1.0,\"Id\":\"<generated-currency-id>\"}],\"descriptors\":[{\"newSObjectWithDefaultsCurrency\":\"USD\",\"defaultValue\":\"USD\",\"defaultedOnCreate\":true,\"type\":\"PICKLIST\",\"object\":\"GladeCurrencyParent__c\"},{\"newSObjectWithDefaultsCurrency\":\"USD\",\"defaultValue\":\"USD\",\"defaultedOnCreate\":true,\"type\":\"PICKLIST\",\"object\":\"Opportunity\"}],\"userDefault\":\"USD\",\"multiCurrency\":true,\"mode\":\"explicit\"}';\n        else {System.assert(false,'Unknown currency observation mode');return;}\n        Map<String,Object> actual=(Map<String,Object>)JSON.deserializeUntyped(JSON.serialize(observed));\n        List<Object> currencies=(List<Object>)actual.get('corporateCurrencies');\n        System.assertEquals(1,currencies.size(),'Exactly one corporate currency');\n        Map<String,Object> corporateRow=(Map<String,Object>)currencies[0];\n        String currencyId=(String)corporateRow.get('Id');\n        System.assertNotEquals(null,currencyId,'Generated currency Id retained');\n        System.assertEquals(18,currencyId.length(),'Generated currency Id length');\n        System.assertEquals(true,currencyId.startsWith('01L'),'CurrencyType Id prefix');\n        Id typedCurrencyId=(Id)currencyId;\n        System.assertEquals(CurrencyType.SObjectType,typedCurrencyId.getSObjectType(),'Generated Id identifies CurrencyType');\n        Map<String,Object> attributes=(Map<String,Object>)corporateRow.get('attributes');\n        System.assertEquals('/services/data/v67.0/sobjects/CurrencyType/'+currencyId,attributes.get('url'),'Exact response API and generated identity in URL');\n        corporateRow.put('Id','<generated-currency-id>');\n        attributes.put('url','<generated-currency-url>');\n        compareCurrencyValue(JSON.deserializeUntyped(expectedJSON),actual,'observation');\n    }\n    private static void compareCurrencyValue(Object expected,Object actual,String path) {\n        if(expected instanceof Map<String,Object>){\n            System.assert(actual instanceof Map<String,Object>,'Expected map '+path);\n            Map<String,Object> want=(Map<String,Object>)expected;Map<String,Object> got=(Map<String,Object>)actual;\n            System.assertEquals(want.keySet(),got.keySet(),'Exact keys '+path);\n            for(String key:want.keySet())compareCurrencyValue(want.get(key),got.get(key),path+'.'+key);\n        }else if(expected instanceof List<Object>){\n            System.assert(actual instanceof List<Object>,'Expected list '+path);\n            List<Object> want=(List<Object>)expected;List<Object> got=(List<Object>)actual;\n            System.assertEquals(want.size(),got.size(),'Exact length '+path);\n            for(Integer i=0;i<want.size();i++)compareCurrencyValue(want[i],got[i],path+'['+i+']');\n        }else System.assertEquals(expected,actual,'Exact value '+path);\n    }\n}\n")
	writeFile(t, filepath.Join(root, "force-app/main/default/classes/GladeCurrencyDefaultsObserve53.cls-meta.xml"), "<ApexClass xmlns=\"http://soap.sforce.com/2006/04/metadata\"><apiVersion>53.0</apiVersion><status>Active</status></ApexClass>\n")
	writeFile(t, filepath.Join(root, "force-app/main/default/triggers/GladeCurrencyParentTrace53.trigger"), "trigger GladeCurrencyParentTrace53 on GladeCurrencyParent__c (before insert, after insert) {\n    for (SObject item : Trigger.new) GladeCurrencyTrace53.record(Trigger.isBefore ? 'beforeInsert' : 'afterInsert',item);\n}\n")
	writeFile(t, filepath.Join(root, "force-app/main/default/triggers/GladeCurrencyParentTrace53.trigger-meta.xml"), "<ApexTrigger xmlns=\"http://soap.sforce.com/2006/04/metadata\"><apiVersion>53.0</apiVersion><status>Active</status></ApexTrigger>\n")
	writeFile(t, filepath.Join(root, "force-app/main/default/triggers/GladeCurrencyOpportunityTrace53.trigger"), "trigger GladeCurrencyOpportunityTrace53 on Opportunity (before insert, after insert) {\n    for (SObject item : Trigger.new) GladeCurrencyTrace53.record(Trigger.isBefore ? 'beforeInsert' : 'afterInsert',item);\n}\n")
	writeFile(t, filepath.Join(root, "force-app/main/default/triggers/GladeCurrencyOpportunityTrace53.trigger-meta.xml"), "<ApexTrigger xmlns=\"http://soap.sforce.com/2006/04/metadata\"><apiVersion>53.0</apiVersion><status>Active</status></ApexTrigger>\n")
	writeFile(t, filepath.Join(root, "force-app/main/default/objects/GladeCurrencyParent__c/GladeCurrencyParent__c.object-meta.xml"), "<CustomObject xmlns=\"http://soap.sforce.com/2006/04/metadata\"><label>Glade Currency Parent</label><pluralLabel>Glade Currency Parents</pluralLabel><nameField><label>Name</label><type>Text</type></nameField><deploymentStatus>Deployed</deploymentStatus><sharingModel>ReadWrite</sharingModel></CustomObject>\n")
	writeFile(t, filepath.Join(root, "force-app/main/default/objects/GladeCurrencyParent__c/fields/Amount__c.field-meta.xml"), "<CustomField xmlns=\"http://soap.sforce.com/2006/04/metadata\"><fullName>Amount__c</fullName><label>Amount</label><type>Currency</type><precision>18</precision><scale>2</scale><required>false</required></CustomField>\n")
	writeFile(t, filepath.Join(root, "force-app/main/default/objects/Opportunity/fields/GladeCurrencyParent__c.field-meta.xml"), "<CustomField xmlns=\"http://soap.sforce.com/2006/04/metadata\"><fullName>GladeCurrencyParent__c</fullName><label>Glade Currency Parent</label><type>Lookup</type><referenceTo>GladeCurrencyParent__c</referenceTo><relationshipLabel>Opportunities</relationshipLabel><relationshipName>GladeCurrencyOpportunities</relationshipName><required>false</required><deleteConstraint>SetNull</deleteConstraint></CustomField>\n")
	writeFile(t, filepath.Join(root, "sfdx-project.json"), "{\"sourceApiVersion\": \"53.0\", \"packageDirectories\": [{\"path\": \"force-app\", \"default\": true}]}")
	// Explicit test org shape matches the admitted feature prerequisite.
	writeFile(t, filepath.Join(root, "glade.yml"), "org:\n  features: [MultiCurrency]\n")
	// The admitted org REST context is 67; all original source/components remain 53.
	run := Run(loadTestIndex(t, root), Options{RuntimeRESTAPIVersion: "67.0"})
	if got := run.Summary(); got.Total != 3 || got.Passed != 3 || got.Failed != 0 || got.Errors != 0 {
		data, _ := json.Marshal(run)
		t.Fatalf("Currency default lifecycle: %s", data)
	}
}
